import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.yO0biSGH.js";const q=JSON.parse('{"title":"风格样张（正样， PROMPT 少样本用）","description":"","frontmatter":{},"headers":[],"relativePath":"ryugi/specs/2026-11-03-style-samples.md","filePath":"ryugi/specs/2026-11-03-style-samples.md","lastUpdated":1793667649000}'),r={name:"ryugi/specs/2026-11-03-style-samples.md"};function s(c,e,n,p,i,l){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="风格样张-正样-prompt-少样本用" tabindex="-1">风格样张（正样， PROMPT 少样本用） <a class="header-anchor" href="#风格样张-正样-prompt-少样本用" aria-label="Permalink to &quot;风格样张（正样， PROMPT 少样本用）&quot;">​</a></h1><p>来源：澄清文档样张 C2（叙事开法）与样张 D（机制层深度），2026-11-03 所有权人核准。</p><h2 id="样张-c2-·-提纲挈领的叙事开法-多态节开头" tabindex="-1">样张 C2 · 提纲挈领的叙事开法（多态节开头） <a class="header-anchor" href="#样张-c2-·-提纲挈领的叙事开法-多态节开头" aria-label="Permalink to &quot;样张 C2 · 提纲挈领的叙事开法（多态节开头）&quot;">​</a></h2><p>你已经会用 Java 的多态：声明一个 <code>Sender</code> 接口，让 SMS、Email 各自 <code>implements</code>，然后拿父类引用指向子类对象。现在把这套搬进 Go，你会发现 <code>implements</code> 这个关键字不存在了，但多态还在。这一节就讲两件事：<strong>关系怎么建立</strong>，和<strong>调用怎么发生</strong>。</p><p>先看关系。Go 不要求类型声明&quot;我实现了谁&quot;；只要你的方法集合里凑齐了接口要求的方法，赋值的那一刻关系就成立了。这带来一个 Java 给不了的自由：你可以给标准库的类型配一个自己定义的接口，因为不需要改对方的源码。</p><p>再看调用。写下一行 <code>sender.Send(&quot;hi&quot;)</code> 时，编译器不知道 <code>sender</code> 里装的是谁，它生成的指令是：查这个组合的 itab，取函数地址，间接跳转。Java 的 <code>invokeinterface</code> 做的也是这件事，所以性能不用担心，两者同量级。</p><p>那 Java 的继承呢？Go 把这条路堵死了：没有 extends，嵌入只是编译期把内层方法&quot;抄写&quot;到外层，内层方法被调用时，接收者永远是内层自己，不存在虚方法。想要&quot;调用方不改一行代码、行为随实现变&quot;，Go 只剩接口这一条路。这也是为什么 Go 社区说：复用靠嵌入，多态靠接口。</p><h2 id="样张-d-·-机制层深度-接口调用的运行时行为" tabindex="-1">样张 D · 机制层深度（接口调用的运行时行为） <a class="header-anchor" href="#样张-d-·-机制层深度-接口调用的运行时行为" aria-label="Permalink to &quot;样张 D · 机制层深度（接口调用的运行时行为）&quot;">​</a></h2><p>同一行 <code>sender.Send(&quot;欢迎注册&quot;)</code>，编译器生成的是间接调用：<code>sender</code> 不只是&quot;一个值&quot;，它是一个两字结构 <code>(类型信息, 数据指针)</code>。类型信息里存着这个&quot;接口 × 具体类型&quot;组合的方法地址表 itab；调用时取 <code>itab.fun[0]</code> 间接跳转。Java 的 <code>invokeinterface</code> 做的是同一类事，查 vtable 槽位再调用。所以两种多态的<strong>运行时成本同量级</strong>，真正的差异在<strong>关系怎么建立</strong>：</p><p>推论（Java 视角）：Go 没有&quot;继承树上的多态&quot;，只有&quot;接口上的多态&quot;。嵌入（struct 嵌入）是编译期转发糖，<code>c.Hello()</code> 改写成 <code>c.Base.Hello()</code>，内层不知道外层存在，没有虚方法、没有 override。想要&quot;改一行代码，所有调用点行为变化&quot;，Go 里只有接口赋值这一条路。</p>',10)])])}const m=o(r,[["render",s]]);export{q as __pageData,m as default};
